-- More of the catalogue: sub-categories for every group, 18 new foods, and USDA nutrition for foods that had none
-- (closest matches say so in their name). Generated from the USDA SR Legacy CSV; idempotent. Run by migration 0020 and the seeder.
-- New foods carry no verdicts until reviewed, like every food added before them.



UPDATE foods f SET subcategory_id = s.id FROM food_subcategories s JOIN food_categories c ON c.id = s.category_id WHERE c.slug = 'grains' AND s.slug = 'rice' AND f.category_id = c.id AND f.slug IN ('white-rice', 'red-rice', 'khichuri', 'biryani', 'polao', 'chira-muri');
UPDATE foods f SET subcategory_id = s.id FROM food_subcategories s JOIN food_categories c ON c.id = s.category_id WHERE c.slug = 'grains' AND s.slug = 'breads' AND f.category_id = c.id AND f.slug IN ('atta-ruti', 'paratha', 'luchi-puri', 'white-bread', 'brown-bread', 'maida');
