UPDATE foods f SET subcategory_id = s.id FROM food_subcategories s JOIN food_categories c ON c.id = s.category_id WHERE c.slug = 'sweets' AND s.slug = 'sugar' AND f.category_id = c.id AND f.slug IN ('sugar-gur', 'honey');
