-- Photos (Pixabay Content License, checked by eye and by tags: the right food, no people or logos, not AI-generated):
-- files in database/assets/photos, credits in CREDITS.md there. Foods get one only where they had none.
SELECT 'media/photo-' || pick.name, 'image/webp', 'asset:photos/' || pick.name || '.webp', 'pixabay', 'Pixabay Content License'
FROM (VALUES
  ('food-bangi'),
  ('food-barbati'),
  ('food-cashew'),
  ('food-coconut'),
  ('food-coconut-milk'),
  ('food-condensed-milk'),
  ('food-frozen-snacks'),
  ('food-green-chili'),
  ('food-kochu'),
  ('food-liver'),
  ('food-maida'),
  ('food-palm-oil'),
  ('food-peanut-butter'),
  ('food-polao'),
  ('food-powdered-milk'),
  ('food-pumpkin-seeds'),
  ('food-sajna'),
  ('food-soy-milk'),
  ('food-tetul'),
  ('food-tofu'),
  ('post-16-8-time-restricted-eating'),
  ('post-eat-vegetables-and-protein-first'),
  ('post-fatty-liver-and-food'),
  ('post-glycemic-index-and-load-explained'),
  ('post-how-cooking-changes-food'),
  ('post-ramadan-and-diabetes'),
  ('recipe-begun-bhorta'),
  ('recipe-chicken-jhol-skinless'),
  ('recipe-doi-with-fruit'),
  ('recipe-masoor-dal-low-oil'),
  ('recipe-rui-fish-jhol'),
  ('recipe-shim-bhaji'),
  ('recipe-shosha-tomato-salad'),
  ('recipe-spiced-yogurt-drink')
) AS pick(name)
ON CONFLICT (directory) DO NOTHING;

UPDATE foods AS food SET media_id = media.id
FROM media WHERE media.source_url = 'asset:photos/food-' || food.slug || '.webp' AND food.media_id IS NULL;
